def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find barrier column (contains 2)
    barrier_col = None
    for c in range(cols):
        barrier_col = c
        for r in range(rows):
            if grid[r][c] == 2:
                break
        if grid[barrier_col] and barrier_col < cols:
            if any(grid[r][barrier_col] == 2 for r in range(rows)):
                break

    if barrier_col is None:
        return grid

    # Find background and object colors
    background = grid[0][0]
    object_color = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and grid[r][c] != 2:
                object_color = grid[r][c]
                break
        if object_color is not None:
            break

    # Build output
    result = [[background for _ in range(cols)] for _ in range(rows)]

    # Preserve barrier
    for r in range(rows):
        result[r][barrier_col] = 2

    # For rows that had the object, add echo and marker
    if object_color is not None:
        for r in range(rows):
            has_object_in_row = any(grid[r][c] == object_color for c in range(cols))
            if has_object_in_row:
                # Echo at barrier + 1
                if barrier_col + 1 < cols:
                    result[r][barrier_col + 1] = object_color
                # Marker at barrier + 2
                if barrier_col + 2 < cols:
                    result[r][barrier_col + 2] = 8

    return result
